#!/usr/bin/env node
/**
 * ULS JIT Generator - Tailwind-like CSS Generation
 * 
 * This script implements a Just-In-Time (JIT) approach similar to Tailwind CSS:
 * 1. Scans project files to extract class names
 * 2. Generates a custom LESS file with only needed utilities/components
 * 3. Compiles that LESS file to CSS
 * 
 * This results in smaller CSS files - only what you use gets included.
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs'
import { resolve, dirname } from 'path'
import { getPurgeCSSConfig } from './purgecss-config.mjs'

/**
 * Map of utility class patterns to their LESS file locations
 * This tells us which LESS file contains each utility class
 */
const UTILITY_MAP = {
  // Spacing utilities (mg*, pd*, gp*)
  spacing: {
    pattern: /^(mg|pd|gp)[xy]?\d+$|^(mg|pd|gp)[tblrxy]?\d+$|^(mg|pd|gp)[xy]?-auto$|^(mgn|mgxn|mgyn|mgtn|mgbn|mgln|mgrn)\d+$/,
    file: 'uls-styles/less/base/utill.less',
    section: 'spacing'
  },
  
  // Typography utilities
  typography: {
    pattern: /^text-(xs|sm|base|lg|xl|start|end|center|justify|left|right|uppercase|lowercase|capitalize|none|sentence-case)$|^h[1-7]$|^font-(light|regular|medium|semibold|bold)$|^leading-(tight|normal|relaxed|loose)$/,
    file: 'uls-styles/less/base/utill.less',
    section: 'typography'
  },
  
  // Display & Position utilities
  display: {
    pattern: /^(block|inline|inline-block|table|none|contents|flex|grid)$|^(static|relative|absolute|fixed|sticky)$/,
    file: 'uls-styles/less/base/utill.less',
    section: 'display'
  },
  
  // Size utilities
  size: {
    pattern: /^w-(auto|100|min|max|fit|100p|\d+-\d+|\d+px)$|^h-(auto|100|screen|100p|\d+px)$/,
    file: 'uls-styles/less/base/utill.less',
    section: 'size'
  },
  
  // Grid utilities
  grid: {
    pattern: /^uls-grid$|^uls-column$|^cols-\d+$|^gap-\d+$|^col-(xs|sm|md|lg)-|^align-(start|center|end|stretch)$|^justify-(start|center|end|between)$|^center-all$/,
    file: 'uls-styles/less/base/grid.less',
    section: 'grid'
  },
  
  // Color utilities
  color: {
    pattern: /^bg-(primary|secondary|success|warning|danger|info|body|surface|surface-elevated|overlay|backdrop)$|^fg-(primary|secondary|success|warning|danger|info|text|text-muted|text-light|heading|subheading)$|^border-(primary|secondary|success|warning|danger|info|muted|light|dark)$/,
    file: 'uls-styles/less/base/utill.less',
    section: 'color'
  },
  
  // Component classes (uls-*)
  components: {
    pattern: /^uls-[a-z-]+/,
    file: null, // Components are in elements/, collections/, modules/
    section: 'components'
  }
}

/**
 * Component file mapping
 * Maps component class prefixes to their LESS files
 */
const COMPONENT_MAP = {
  'uls-button': 'uls-styles/less/elements/button.less',
  'uls-input': 'uls-styles/less/elements/input.less',
  'uls-input-text': 'uls-styles/less/elements/input-text.less',
  'uls-input-textarea': 'uls-styles/less/elements/input-textarea.less',
  'uls-input-num': 'uls-styles/less/elements/input-num.less',
  'uls-input-switch': 'uls-styles/less/elements/input-switch.less',
  'uls-input-group': 'uls-styles/less/elements/Input-group.less',
  'uls-radio': 'uls-styles/less/elements/radio.less',
  'uls-select-button': 'uls-styles/less/elements/select-button.less',
  'uls-checkbox': 'uls-styles/less/elements/checkbox.less',
  'uls-dropdown': 'uls-styles/less/elements/dropdown.less',
  'uls-card': 'uls-styles/less/collections/card.less',
  'uls-accordion': 'uls-styles/less/collections/accordion.less',
  'uls-tab': 'uls-styles/less/collections/tab.less',
  'uls-dialog': 'uls-styles/less/modules/dialog.less',
  'uls-tooltip': 'uls-styles/less/modules/tooltip.less',
  'uls-toast': 'uls-styles/less/modules/toast.less',
  // Add more components as needed
}

/**
 * Extract class names from content using the same logic as purgecss-config
 */
function extractClassNames(content) {
  const classNames = new Set()
  
  // 1. Standard class="..." and className="..." attributes
  const classAttrRegex = /\bclass(Name)?\s*=\s*["'`]([^"'`]+)["'`]/g
  let match
  while ((match = classAttrRegex.exec(content)) !== null) {
    const classes = match[2].split(/\s+/).filter(Boolean)
    classes.forEach(cls => classNames.add(cls))
  }
  
  // 2. Template literals
  const templateLiteralRegex = /\bclass(Name)?\s*=\s*\{`([^`]+)`\}/g
  while ((match = templateLiteralRegex.exec(content)) !== null) {
    const templateContent = match[2]
    const parts = templateContent.split(/\$\{[^}]+\}/)
    parts.forEach(part => {
      const classes = part.trim().split(/\s+/).filter(Boolean)
      classes.forEach(cls => classNames.add(cls))
    })
  }
  
  // 3. classNames() or clsx() function calls
  const classNamesRegex = /\b(classNames?|clsx)\s*\(([^)]+)\)/g
  while ((match = classNamesRegex.exec(content)) !== null) {
    const inside = match[2]
    const stringRegex = /["'`]([^"'`]+)["'`]/g
    let strMatch
    while ((strMatch = stringRegex.exec(inside)) !== null) {
      const classes = strMatch[1].split(/\s+/).filter(Boolean)
      classes.forEach(cls => classNames.add(cls))
    }
    const objectKeyRegex = /['"]([^'"]+)['"]\s*:/g
    while ((strMatch = objectKeyRegex.exec(inside)) !== null) {
      classNames.add(strMatch[1])
    }
  }
  
  return Array.from(classNames)
}

/**
 * Categorize classes into utilities and components
 */
function categorizeClasses(classNames) {
  const utilities = {
    spacing: new Set(),
    typography: new Set(),
    display: new Set(),
    size: new Set(),
    grid: new Set(),
    color: new Set(),
  }
  const components = new Set()
  const themes = new Set()
  const other = new Set()
  
  for (const className of classNames) {
    // Check if it's a theme class
    if (/^uls-.*-theme$/.test(className) || /^uls-.*-mode$/.test(className)) {
      themes.add(className)
      continue
    }
    
    // Check utility patterns
    let categorized = false
    for (const [category, config] of Object.entries(UTILITY_MAP)) {
      if (config.pattern && config.pattern.test(className)) {
        if (utilities[category]) {
          utilities[category].add(className)
          categorized = true
          break
        }
      }
    }
    
    // Check component patterns
    if (!categorized && className.startsWith('uls-')) {
      components.add(className)
      categorized = true
    }
    
    if (!categorized) {
      other.add(className)
    }
  }
  
  return {
    utilities: Object.fromEntries(
      Object.keys(utilities).map(key => [key, Array.from(utilities[key])])
    ),
    components: Array.from(components),
    themes: Array.from(themes),
    other: Array.from(other)
  }
}

/**
 * Generate a custom LESS file with only needed utilities/components
 */
function generateCustomLessFile(categorized, projectRoot) {
  const imports = []
  const customRules = []
  
  // Always import base files (variables, reset, mixins)
  imports.push('// ==========================================================================')
  imports.push('// BASE FILES (Always Required)')
  imports.push('// ==========================================================================')
  imports.push('@import "uls-styles/less/base/typography-vars";')
  imports.push('@import "uls-styles/less/base/color-vars";')
  imports.push('@import "uls-styles/less/base/common-vars";')
  imports.push('@import "uls-styles/less/base/container-vars";')
  imports.push('@import "uls-styles/less/base/size-vars";')
  imports.push('@import "uls-styles/less/base/palette";')
  imports.push('@import "uls-styles/less/base/root-config";')
  imports.push('@import "uls-styles/less/base/reset";')
  imports.push('@import "uls-styles/less/base/component-mixins";')
  imports.push('@import "uls-styles/less/base/transition";')
  imports.push('@import "uls-styles/less/base/colors-mixins";')
  imports.push('')
  
  // Import utility files if any utilities are used
  const hasUtilities = Object.values(categorized.utilities).some(arr => arr.length > 0)
  if (hasUtilities) {
    imports.push('// ==========================================================================')
    imports.push('// UTILITY CLASSES (Only what you use)')
    imports.push('// ==========================================================================')
    
    // Import utility file (it will be filtered by PurgeCSS later)
    imports.push('@import "uls-styles/less/base/utill";')
    
    if (categorized.utilities.grid.length > 0) {
      imports.push('@import "uls-styles/less/base/grid";')
    }
    
    imports.push('')
  }
  
  // Import typography and common if needed
  if (categorized.utilities.typography.length > 0) {
    imports.push('@import "uls-styles/less/base/typography";')
  }
  imports.push('@import "uls-styles/less/base/common";')
  imports.push('@import "uls-styles/less/base/container";')
  imports.push('')
  
  // Import components that are used
  if (categorized.components.length > 0) {
    imports.push('// ==========================================================================')
    imports.push('// COMPONENT CLASSES (Only what you use)')
    imports.push('// ==========================================================================')
    
    const componentFiles = new Set()
    for (const componentClass of categorized.components) {
      // Extract component name (e.g., "uls-button" -> "uls-button")
      const componentName = componentClass.split(' ')[0].split('-').slice(0, 2).join('-')
      if (COMPONENT_MAP[componentName]) {
        componentFiles.add(COMPONENT_MAP[componentName])
      }
    }
    
    for (const file of Array.from(componentFiles).sort()) {
      imports.push(`@import "${file}";`)
    }
    imports.push('')
  }
  
  // Always import themes (they're dynamically toggled)
  imports.push('// ==========================================================================')
  imports.push('// THEMES (Always included - dynamically toggled)')
  imports.push('// ==========================================================================')
  imports.push('@import "uls-styles/less/themes/uls-light";')
  imports.push('@import "uls-styles/less/themes/uls-dark";')
  imports.push('@import "uls-styles/less/themes/uls-cardinal";')
  imports.push('@import "uls-styles/less/themes/uls-cobalt";')
  imports.push('@import "uls-styles/less/themes/uls-dark-cardinal";')
  imports.push('@import "uls-styles/less/themes/uls-dark-cobalt";')
  
  return imports.join('\n')
}

/**
 * Main JIT generation function
 */
export async function generateJITLess(options = {}) {
  const { projectRoot = process.cwd(), outputFile } = options
  
  console.log('🚀 ULS JIT Generator - Tailwind-like CSS Generation\n')
  
  // Step 1: Get class names from content files (reuse purgecss config)
  const purgeConfig = getPurgeCSSConfig({ scanJsFiles: true })
  
  // Step 2: Read and extract classes from content files
  const { glob } = await import('glob')
  const { readFileSync } = await import('fs')
  const { resolve } = await import('path')
  
  const allClassNames = new Set()
  
  // Scan all content files
  for (const pattern of purgeConfig.content) {
    try {
      const files = glob.sync(pattern, { 
        cwd: projectRoot,
        absolute: true,
        ignore: ['node_modules/**', 'dist/**']
      })
      
      for (const file of files) {
        try {
          const content = readFileSync(file, 'utf8')
          const classes = extractClassNames(content)
          classes.forEach(cls => allClassNames.add(cls))
        } catch (err) {
          // Skip files that can't be read
        }
      }
    } catch (err) {
      // Pattern might not match, continue
    }
  }
  
  console.log(`✅ Found ${allClassNames.size} unique class names`)
  
  // Step 3: Categorize classes
  const categorized = categorizeClasses(Array.from(allClassNames))
  
  console.log('\n📊 Class Breakdown:')
  console.log(`   Utilities: ${Object.values(categorized.utilities).flat().length}`)
  console.log(`   Components: ${categorized.components.length}`)
  console.log(`   Themes: ${categorized.themes.length}`)
  console.log(`   Other: ${categorized.other.length}`)
  
  // Step 4: Generate custom LESS file
  const customLess = generateCustomLessFile(categorized, projectRoot)
  
  // Step 5: Write custom LESS file
  const outputPath = outputFile || resolve(projectRoot, 'src/styles/uls-jit.less')
  const outputDir = dirname(outputPath)
  if (!existsSync(outputDir)) {
    mkdirSync(outputDir, { recursive: true })
  }
  
  writeFileSync(outputPath, customLess, 'utf8')
  console.log(`\n✅ Generated custom LESS file: ${outputPath}`)
  
  return {
    classNames: Array.from(allClassNames),
    categorized,
    outputPath
  }
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  generateJITLess().catch(console.error)
}

